-- checks: a table held only in a high register of a foreach callback inside a coroutine survives the collection the host's 64 MiB heap limit forces at the callback's first budget stop, and is intact when the run continues.
-- KEYS: []
-- ARGV: []
-- expects: No pre-existing keys. The main chunk holds a 40 MiB string. The coroutine body's 180 locals raise the callback's frame, and the callback's 150 further locals put the fresh table about 80 slots past the coroutine stack's length at callback entry. Before its first call or loop the callback makes a 40 MiB string and drops it at once. At budget 1 that first loop stops the run inside the callback, so a host with a 64 MiB heap limit collects while only the parked copy of the coroutine's stack holds the table; the decoy tables made afterwards would reuse its slot had that collection freed it.
local big = string.rep("a", 40 * 1048576)
local keep = {}
local function visit(key, value)
  local v1, v2, v3, v4, v5, v6, v7, v8, v9, v10, v11, v12, v13, v14, v15, v16, v17, v18, v19, v20, v21, v22, v23, v24, v25, v26, v27, v28, v29, v30, v31, v32, v33, v34, v35, v36, v37, v38, v39, v40, v41, v42, v43, v44, v45, v46, v47, v48, v49, v50, v51, v52, v53, v54, v55, v56, v57, v58, v59, v60, v61, v62, v63, v64, v65, v66, v67, v68, v69, v70, v71, v72, v73, v74, v75, v76, v77, v78, v79, v80, v81, v82, v83, v84, v85, v86, v87, v88, v89, v90, v91, v92, v93, v94, v95, v96, v97, v98, v99, v100, v101, v102, v103, v104, v105, v106, v107, v108, v109, v110, v111, v112, v113, v114, v115, v116, v117, v118, v119, v120, v121, v122, v123, v124, v125, v126, v127, v128, v129, v130, v131, v132, v133, v134, v135, v136, v137, v138, v139, v140, v141, v142, v143, v144, v145, v146, v147, v148, v149, v150
  local fresh = {tag = "fresh"}
  local width = #(big .. "x")
  for i = 1, 32 do keep[#keep + 1] = {tag = "decoy"} end
  return key .. "=" .. tostring(fresh.tag) .. "/" .. width
end
local co = coroutine.create(function()
  local c1, c2, c3, c4, c5, c6, c7, c8, c9, c10, c11, c12, c13, c14, c15, c16, c17, c18, c19, c20, c21, c22, c23, c24, c25, c26, c27, c28, c29, c30, c31, c32, c33, c34, c35, c36, c37, c38, c39, c40, c41, c42, c43, c44, c45, c46, c47, c48, c49, c50, c51, c52, c53, c54, c55, c56, c57, c58, c59, c60, c61, c62, c63, c64, c65, c66, c67, c68, c69, c70, c71, c72, c73, c74, c75, c76, c77, c78, c79, c80, c81, c82, c83, c84, c85, c86, c87, c88, c89, c90, c91, c92, c93, c94, c95, c96, c97, c98, c99, c100, c101, c102, c103, c104, c105, c106, c107, c108, c109, c110, c111, c112, c113, c114, c115, c116, c117, c118, c119, c120, c121, c122, c123, c124, c125, c126, c127, c128, c129, c130, c131, c132, c133, c134, c135, c136, c137, c138, c139, c140, c141, c142, c143, c144, c145, c146, c147, c148, c149, c150, c151, c152, c153, c154, c155, c156, c157, c158, c159, c160, c161, c162, c163, c164, c165, c166, c167, c168, c169, c170, c171, c172, c173, c174, c175, c176, c177, c178, c179, c180
  local result = table.foreach({"only"}, visit)
  return result
end)
local ok, result = coroutine.resume(co)
return {tostring(ok), tostring(result), #keep, #big}
